<?php
    class ListTripsHandler extends Handler {
        public function handle($input) {
            global $processorProvider;

            $type = isset($input["type"]) ? $input["type"] : "regular";
            unset($input["type"]);

            $response = array();    
            if ($type == "regular") {
                $response = $processorProvider->run("GetTrips", $input);
            }
            else if ($type == "candidate") { 
                $response = $processorProvider->run("GetCandidateTrips", $input);
            }

            return $this->createResponse(200, $response);
        }

        public function getTag() {
            return "Trips";
        }

        public function getPath() {
            return "/trips";
        }

        public function getParameters() {
            return array(
                $this->createQueryParameter("yearId", "integer", 2024),
                $this->createQueryParameter("type", "string", array("regular", "candidate")),
                $this->createQueryParameter("includeExpenses", "boolean", "false"),
                $this->createQueryParameter("includeStays", "boolean", "false"),
                $this->createQueryParameter("includeFlights", "boolean", "false"),
                $this->createQueryParameter("includeWatchedFlights", "boolean", "false"),
                $this->createQueryParameter("includeLayovers", "boolean", "false"),
                $this->createQueryParameter("includeFitness", "boolean", "false"),
                $this->createQueryParameter("includeNotes", "boolean", "false"),
                $this->createQueryParameter("includeStats", "boolean", "false"),
                $this->createQueryParameter("includePublicHolidays", "boolean", "false"));
        }

        public function getMethod() {
            return "GET";
        }

        public function getOperationId() {
            return "list_trips";
        }
        
        public function getShortDescription() {
            return "Retrieve a collection of trips";
        }
        
        public function getLongDescription() {
            return "Retrieves a collection of trips matching the specified filters. If the `type` filter is not specified, the value `regular` will be used as a default. Some fields in the result may be omitted due to performance reasons, these can be enabled by various include filters.";
        }
        
